public static int calculateTimeNeeded(int N) {
  int timeNeeded = 0;

  for (int i = 0; i < N; i++) {
    timeNeeded++;
    for (int j = 0; j < N - 1; j++) {
      if (j % 2 == 0) {
        if (j == N - 2) {
          break;
        }
        if (i == j) {
          i++;
        }
      } else {
        if (i == j) {
          i--;
        }
      }
    }
  }

  return timeNeeded;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    permute(nums, 0, new ArrayList<>(), result);
    return result;
}

private void permute(int[] nums, int start, List<Integer> curr, List<List<Integer>> result) {
    if (start == nums.length) {
        result.add(new ArrayList<>(curr));
        return;
    }
    for (int i = start; i < nums.length; i++) {
        curr.add(nums[i]);
        permute(nums, i + 1, curr, result);
        curr.remove(curr.size() - 1);
    }
}

