public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with n nodes and edges
    Graph graph = new Graph(n, edges);

    // Initialize a queue to store the nodes to visit
    Queue<Integer> queue = new LinkedList<>();

    // Initialize a boolean array to mark the visited nodes
    boolean[] visited = new boolean[n];

    // Initialize a variable to store the minimum time
    int minTime = 0;

    // Start from node 0
    queue.offer(0);
    visited[0] = true;

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node from the queue
        int current = queue.poll();

        // If the current node has an apple, add the time to collect it to the minimum time
        if (hasApple[current]) {
            minTime += 1;
        }

        // Loop through the neighbors of the current node
        for (int neighbor : graph.getNeighbors(current)) {
            // If the neighbor has not been visited, mark it as visited and add it to the queue
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.offer(neighbor);
            }
        }
    }

    // Return the minimum time
    return minTime;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    int[] charCount = new int[26];

    for (char c : s.toCharArray()) {
        charCount[c - 'a']++;
    }

    while (result.length() < s.length()) {
        int min = -1;
        int max = -1;

        for (int i = 0; i < 26; i++) {
            if (charCount[i] > 0 && (min == -1 || min > i)) {
                min = i;
            }
            if (charCount[i] > 0 && (max == -1 || max < i)) {
                max = i;
            }
        }

        if (min != -1) {
            result.append((char) (min + 'a'));
            charCount[min]--;
        }

        if (max != -1) {
            result.append((char) (max + 'a'));
            charCount[max]--;
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the sum of the array elements
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // Calculate the average of the array elements
    int average = sum / nums.length;

    // Check if the average is an integer
    if (average % 1 != 0) {
        return false;
    }

    // Check if the array can be split into two non-empty arrays with the same average
    for (int i = 0; i < nums.length; i++) {
        int sum1 = 0;
        for (int j = i; j < nums.length; j++) {
            sum1 += nums[j];
            if (sum1 == average) {
                return true;
            }
        }
    }

    return false;
}

