public static int squarePermutations(int[] A) {
    // Initialize a set to store the unique permutations
    Set<String> permutations = new HashSet<>();

    // Loop through all possible permutations of the array
    for (int i = 0; i < A.length; i++) {
        int[] perm = new int[A.length];
        for (int j = 0; j < A.length; j++) {
            perm[j] = A[j];
        }
        Arrays.sort(perm);
        permutations.add(Arrays.toString(perm));
    }

    // Count the number of square permutations
    int count = 0;
    for (String perm : permutations) {
        int sum = 0;
        for (int i = 0; i < perm.length() - 1; i++) {
            sum += (perm.charAt(i) - '0') * (perm.charAt(i + 1) - '0');
        }
        if (sum * sum == perm.length()) {
            count++;
        }
    }

    return count;
}

