public static boolean isBoomerang(int[][] points) {
    // Check if the points form a triangle
    if (points.length != 3) {
        return false;
    }

    // Calculate the determinant of the matrix formed by the three points
    int determinant = (points[1][0] - points[0][0]) * (points[2][1] - points[0][1]) - (points[1][1] - points[0][1]) * (points[2][0] - points[0][0]);

    // If the determinant is positive, the points form a boomerang
    return determinant > 0;
}

public static int findNthUglyNumber(int n) {
    int[] dp = new int[n + 1];
    dp[1] = 1;
    int i2 = 1, i3 = 1, i5 = 1;
    for (int i = 2; i <= n; i++) {
        int min = Math.min(dp[i2] * 2, Math.min(dp[i3] * 3, dp[i5] * 5));
        dp[i] = min;
        if (min == dp[i2] * 2) {
            i2++;
        }
        if (min == dp[i3] * 3) {
            i3++;
        }
        if (min == dp[i5] * 5) {
            i5++;
        }
    }
    return dp[n];
}

